import { createMintIgnoreMatcher, isMintIgnoredBy, toPosixPath, } from '@mintlify/common';
import { readdirSync, realpathSync, statSync } from 'fs';
import { readdir } from 'fs/promises';
import path from 'path';
export const getFileListSync = (dirName, og = dirName, mintIgnore = []) => {
    return collectFileListSync(dirName, og, createMintIgnoreMatcher(mintIgnore));
};
const collectFileListSync = (dirName, og, matcher, ancestors = new Set(), root) => {
    const files = [];
    let realDir;
    try {
        realDir = realpathSync(dirName);
    }
    catch {
        return files;
    }
    const realRoot = root ?? realDir;
    if (realDir !== realRoot && !realDir.startsWith(realRoot + path.sep)) {
        return files;
    }
    if (ancestors.has(realDir)) {
        return files;
    }
    ancestors.add(realDir);
    let items;
    try {
        items = readdirSync(dirName, { withFileTypes: true });
    }
    catch {
        ancestors.delete(realDir);
        return files;
    }
    for (const item of items) {
        if (item.name === 'node_modules' || item.name === '.git') {
            continue;
        }
        const fullPath = path.join(dirName, item.name);
        let isDirectory = item.isDirectory();
        if (item.isSymbolicLink()) {
            try {
                isDirectory = statSync(fullPath).isDirectory();
            }
            catch {
                continue;
            }
        }
        const relativePath = toPosixPath(path.relative(og, fullPath));
        if (isMintIgnoredBy(relativePath, matcher, isDirectory)) {
            continue;
        }
        if (isDirectory) {
            const nested = collectFileListSync(fullPath, og, matcher, ancestors, realRoot);
            for (const file of nested) {
                files.push(file);
            }
        }
        else {
            files.push(relativePath);
        }
    }
    ancestors.delete(realDir);
    return files;
};
// TODO consolidate this function
export const getFileListWithDirectories = (dirName, og = dirName, mintIgnore = []) => {
    return collectFileListWithDirectories(dirName, og, createMintIgnoreMatcher(mintIgnore));
};
const collectFileListWithDirectories = (dirName, og, matcher) => {
    const files = [];
    const items = readdirSync(dirName, { withFileTypes: true });
    for (const item of items) {
        const fullPath = path.join(dirName, item.name);
        const relativePath = toPosixPath(path.relative(og, fullPath));
        if (isMintIgnoredBy(relativePath, matcher, item.isDirectory())) {
            continue;
        }
        if (item.isDirectory()) {
            files.push(relativePath);
            const nested = collectFileListWithDirectories(fullPath, og, matcher);
            for (const file of nested) {
                files.push(file);
            }
        }
        else {
            files.push(relativePath);
        }
    }
    return files;
};
export async function* getFileList(dirName, og = dirName, mintIgnore = []) {
    yield* walkFileList(dirName, og, createMintIgnoreMatcher(mintIgnore));
}
async function* walkFileList(dirName, og, matcher) {
    const items = await readdir(dirName, { withFileTypes: true });
    for (const item of items) {
        const fullPath = path.join(dirName, item.name);
        const relativePath = toPosixPath(path.relative(og, fullPath));
        if (isMintIgnoredBy(relativePath, matcher, item.isDirectory())) {
            continue;
        }
        if (item.isDirectory()) {
            yield* walkFileList(fullPath, og, matcher);
        }
        else {
            yield `/${relativePath}`;
        }
    }
}
